function icon(string $name, int $size = 20, string $label = '', string $class = ''): string {
    $paths = ICONS[$name] ?? ICONS['circle-alert'];
    $a11y = $label !== '' ? 'role="img" aria-label="' . htmlspecialchars($label, ENT_QUOTES) . '"' : 'aria-hidden="true" focusable="false"';
    return '<svg class="ce-icon ' . $class . '" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ' . $a11y . '>' . $paths . '</svg>';
}
